parameters.jsCode:
const run = $input.first().json;
const steps = run.intermediateSteps || [];

const clean = value => {
  if (!value) return '';
  if (typeof value === 'object') {
    return value.output ?? value.response ?? value.text ?? JSON.stringify(value);
  }
  try {
    const parsed = JSON.parse(value);
    const first = Array.isArray(parsed) ? parsed[0] : parsed;
    return first.output ?? first.response ?? first.text ?? value;
  } catch {
    return String(value);
  }
};

// محاولة استخراج النتيجة من خطوات الـ Agent، مع Fallback لقراءة النود مباشرة إذا لم توجد
const resultOf = (word, directNodeName) => {
  const step = steps.filter(s => String(s.action?.tool || '').toLowerCase().includes(word)).pop();
  if (step && step.observation) {
    const res = clean(step.observation);
    if (res && res.trim().length > 0) return res;
  }

  // في حال فشل الاستخراج من intermediateSteps، نجلب المخرج مباشرة من النود المنفذة
  if (directNodeName) {
    try {
      const nodeData = $(directNodeName).first().json;
      const res = nodeData.output ?? nodeData.response ?? nodeData.text ?? '';
      if (res && res.trim().length > 0) return clean(res);
    } catch (e) {
      // النود لم تنفذ
    }
  }

  return null;
};

const sections = [
  ['Match Analysis', resultOf('matcher', 'CV Matcher'), 'CV Matcher'],
  ['Tailored Cover Letter', resultOf('letter', 'Cover Letter Writer'), 'Cover Letter Writer'],
  ['Interview Preparation', resultOf('interview', 'Interview Coach'), 'Interview Coach'],
];

const report = [run.output]
  .concat(sections.map(([title, body, agent]) => '## ' + title + '\n\n' + (body || '_The ' + agent + ' did not run this time. Please submit the form again._')))
  .join('\n\n');

return [{ json: { report, specialistsUsed: sections.filter(s => s[1]).length } }];

